<?php require 'common.php'; $rows=$ket_noi->query('SELECT * FROM security_lab_audit ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>Security Audit Log</title><style>body{font-family:Arial;max-width:1200px;margin:25px auto}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:8px;font-size:13px}th{background:#111;color:#fff}.vulnerable{color:#b91c1c}.fixed{color:#15803d}.box{padding:14px;background:#f3f4f6;margin-bottom:18px}</style></head><body><h1>🧾 Security Audit & Verification</h1><div class="box"><b>Mục đích:</b> lưu bằng chứng kiểm thử trước/sau hardening. Mỗi lab ghi scenario, mode, HTTP method/path, status, kết quả và ghi chú.</div><table><tr><th>Time</th><th>Scenario</th><th>Mode</th><th>Method</th><th>Path</th><th>Status</th><th>Result</th><th>Notes</th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['scenario'])?></td><td class="<?=h($r['mode'])?>"><?=h($r['mode'])?></td><td><?=h($r['method'])?></td><td><?=h($r['path'])?></td><td><?=h($r['status_code'])?></td><td><?=h($r['result'])?></td><td><?=h($r['notes'])?></td></tr><?php endforeach; ?></table><p><a href="index.php">← Lab menu</a></p></body></html>